import { apiFetch, getApiBaseUrl, getSiteUrl } from "../lib/siteConfig";

/**
 * PHASE 7C / PHASE 9B — `/llms.txt`.
 *
 * The live index is generated by the API from D1 (newest briefings, active KEV,
 * live families, top actors). This route proxies it so the canonical URL stays
 * `/llms.txt`, and degrades to a static baseline index if the API is briefly
 * unavailable — an answer engine must still get a valid file.
 */

const FALLBACK = (site: string): string => `# ZAYRON-X

> Truth Is the Perimeter. Source-verified vulnerability and malware intelligence with explicit provenance, confidence and decay.

## Authoritative CVE advisories
- [Vulnerability intelligence](${site}/intelligence/vulnerabilities)
- [Methodology and governance](${site}/methodology)

## Neural newsroom
- [Verified cybersecurity briefings](${site}/news): graph-enriched briefings with catalog telemetry attached.

## Live indicators of compromise
- [IOC workspace](${site}/intelligence/iocs): indicators are always defanged and never hyperlinked.

## API
- [OpenAPI 3.1 specification](${site}/api/v1/openapi.json)
- \`GET ${site}/api/v1/news\` — briefing index
- \`GET ${site}/api/v1/vendors\` / \`GET ${site}/api/v1/regions\` — programmatic hubs

## Policies
- [Legal](${site}/legal) · [Malware handling](${site}/malware-handling) · [Security](${site}/security)
`;

async function liveFile(path: string): Promise<string | null> {
  try {
    const response = await apiFetch(`${getApiBaseUrl()}${path}`, {
      headers: { accept: "text/plain" },
      signal: AbortSignal.timeout(8000),
    });
    if (!response.ok) return null;
    const text = await response.text();
    return text.trim().length > 0 ? text : null;
  } catch {
    return null;
  }
}

export const revalidate = 300;

export async function GET(): Promise<Response> {
  const live = await liveFile("/llms.txt");
  const body = live ?? FALLBACK(getSiteUrl());
  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=300, s-maxage=3600",
      "x-llms-source": live ? "live" : "fallback",
    },
  });
}
